/**
 * Meeting Analyzer Helper
 * Analyzes meeting properties like attendee count and duration.
 */

/**
 * Get total attendee count (required + optional)
 */
export function getAttendeeCount(): Promise<number> {
  return new Promise((resolve, reject) => {
    const item = Office.context.mailbox.item;
    if (!item) {
      reject(new Error("No active item"));
      return;
    }

    let requiredCount = 0;
    let optionalCount = 0;
    let completedCalls = 0;

    const checkComplete = () => {
      completedCalls++;
      if (completedCalls === 2) {
        resolve(requiredCount + optionalCount);
      }
    };

    item.requiredAttendees.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        requiredCount = result.value.length;
      }
      checkComplete();
    });

    item.optionalAttendees.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        optionalCount = result.value.length;
      }
      checkComplete();
    });
  });
}

/**
 * Get meeting duration in minutes
 */
export function getDurationMinutes(): Promise<number> {
  return new Promise((resolve, reject) => {
    const item = Office.context.mailbox.item;
    if (!item) {
      reject(new Error("No active item"));
      return;
    }

    let startTime: Date | null = null;
    let endTime: Date | null = null;
    let completedCalls = 0;

    const checkComplete = () => {
      completedCalls++;
      if (completedCalls === 2) {
        if (startTime && endTime) {
          const durationMs = endTime.getTime() - startTime.getTime();
          const durationMinutes = Math.round(durationMs / (1000 * 60));
          resolve(durationMinutes);
        } else {
          resolve(0);
        }
      }
    };

    item.start.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        startTime = result.value;
      }
      checkComplete();
    });

    item.end.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        endTime = result.value;
      }
      checkComplete();
    });
  });
}

/**
 * Get meeting start and end times
 */
export function getMeetingTimes(): Promise<{ start: Date; end: Date }> {
  return new Promise((resolve, reject) => {
    const item = Office.context.mailbox.item;
    if (!item) {
      reject(new Error("No active item"));
      return;
    }

    let startTime: Date | null = null;
    let endTime: Date | null = null;
    let completedCalls = 0;

    const checkComplete = () => {
      completedCalls++;
      if (completedCalls === 2) {
        if (startTime && endTime) {
          resolve({ start: startTime, end: endTime });
        } else {
          reject(new Error("Could not get meeting times"));
        }
      }
    };

    item.start.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        startTime = result.value;
      }
      checkComplete();
    });

    item.end.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        endTime = result.value;
      }
      checkComplete();
    });
  });
}

/**
 * Set meeting end time (for duration quick buttons)
 */
export function setMeetingDuration(durationMinutes: number): Promise<void> {
  return new Promise((resolve, reject) => {
    const item = Office.context.mailbox.item;
    if (!item) {
      reject(new Error("No active item"));
      return;
    }

    item.start.getAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Failed) {
        reject(result.error);
        return;
      }

      const startTime = result.value;
      const newEndTime = new Date(startTime.getTime() + durationMinutes * 60 * 1000);

      item.end.setAsync(newEndTime, (setResult) => {
        if (setResult.status === Office.AsyncResultStatus.Succeeded) {
          resolve();
        } else {
          reject(setResult.error);
        }
      });
    });
  });
}

/**
 * Format time for display (e.g., "2:00 PM")
 */
export function formatTime(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });
}

/**
 * Get attendee status message with color level
 */
export function getAttendeeStatusMessage(count: number): {
  message: string;
  level: "success" | "warning" | "error";
} {
  if (count === 0) {
    return {
      message: "No attendees yet",
      level: "warning",
    };
  } else if (count <= 5) {
    return {
      message: `${count} attendee${count !== 1 ? "s" : ""} — Great! Small groups make decisions faster`,
      level: "success",
    };
  } else if (count <= 7) {
    return {
      message: `${count} attendees — Good size for productive discussion`,
      level: "success",
    };
  } else if (count <= 10) {
    return {
      message: `${count} attendees — Consider: Does everyone need to be here?`,
      level: "warning",
    };
  } else {
    return {
      message: `${count} attendees — Could this be an email? Large meetings often lack focus`,
      level: "error",
    };
  }
}

/**
 * Get duration status message with color level
 */
export function getDurationStatusMessage(minutes: number): {
  message: string;
  level: "success" | "warning" | "error";
  showButtons: boolean;
} {
  if (minutes <= 30) {
    return {
      message: `${minutes} min — Perfect length for focused discussion`,
      level: "success",
      showButtons: false,
    };
  } else if (minutes <= 45) {
    return {
      message: `${minutes} min — Good, just keep it tight`,
      level: "success",
      showButtons: false,
    };
  } else if (minutes <= 60) {
    return {
      message: `${minutes} min — Tip: Try 45 min with a tighter agenda`,
      level: "warning",
      showButtons: true,
    };
  } else {
    return {
      message: `${minutes} min — Long meetings lose focus. Can you split this up?`,
      level: "error",
      showButtons: true,
    };
  }
}
