/**
 * Task Pane Logic
 * Handles the POST framework UI for meeting best practices.
 */

import {
  provideFluentDesignSystem,
  fluentButton,
  fluentTextField,
  fluentTextArea,
  fluentBadge,
} from "@fluentui/web-components";

import {
  PostData,
  savePostData,
  loadPostData,
  createEmptyPostData,
  validatePostData,
} from "../helpers/customProperties";

import {
  getAttendeeCount,
  getDurationMinutes,
  getMeetingTimes,
  setMeetingDuration,
  formatTime,
  getAttendeeStatusMessage,
  getDurationStatusMessage,
} from "../helpers/meetingAnalyzer";

import {
  validateFields,
} from "../helpers/postValidator";

import "./taskpane.css";

// Register Fluent UI Web Components
provideFluentDesignSystem().register(
  fluentButton(),
  fluentTextField(),
  fluentTextArea(),
  fluentBadge()
);

// DOM Elements
let attendeeBadge: HTMLElement;
let attendeeCount: HTMLElement;
let durationText: HTMLElement;
let durationButtons: HTMLElement;
let btn30min: HTMLElement;
let btn45min: HTMLElement;
let purposeField: HTMLInputElement;
let outcomesField: HTMLTextAreaElement;
let structureField: HTMLTextAreaElement;
let timingField: HTMLInputElement;
let btnSave: HTMLElement;
let statusMessage: HTMLElement;

// Initialize Office.js
Office.onReady(async () => {
  initializeElements();
  attachEventListeners();
  registerItemChangeHandlers();
  await refreshMeetingInfo();
  await loadFormData();
});

/**
 * Register event handlers for automatic refresh when meeting details change
 */
function registerItemChangeHandlers(): void {
  // Refresh when attendees change
  Office.context.mailbox.item?.addHandlerAsync(
    Office.EventType.RecipientsChanged,
    () => refreshMeetingInfo()
  );

  // Refresh when meeting time changes
  Office.context.mailbox.item?.addHandlerAsync(
    Office.EventType.AppointmentTimeChanged,
    () => refreshMeetingInfo()
  );
}

/**
 * Initialize DOM element references
 */
function initializeElements(): void {
  attendeeBadge = document.getElementById("attendee-badge")!;
  attendeeCount = document.getElementById("attendee-count")!;
  durationText = document.getElementById("duration-text")!;
  durationButtons = document.getElementById("duration-buttons")!;
  btn30min = document.getElementById("btn-30min")!;
  btn45min = document.getElementById("btn-45min")!;
  purposeField = document.getElementById("purpose-field") as HTMLInputElement;
  outcomesField = document.getElementById("outcomes-field") as HTMLTextAreaElement;
  structureField = document.getElementById("structure-field") as HTMLTextAreaElement;
  timingField = document.getElementById("timing-field") as HTMLInputElement;
  btnSave = document.getElementById("btn-save")!;
  statusMessage = document.getElementById("status-message")!;
}

/**
 * Attach event listeners to buttons
 */
function attachEventListeners(): void {
  btn30min.addEventListener("click", () => handleDurationChange(30));
  btn45min.addEventListener("click", () => handleDurationChange(45));
  btnSave.addEventListener("click", () => handleSave());

  // Auto-save on field changes (debounced)
  let saveTimeout: number;
  const debouncedSave = () => {
    clearTimeout(saveTimeout);
    saveTimeout = window.setTimeout(() => {
      handleSave(true); // silent save
    }, 1000);
  };

  purposeField.addEventListener("input", debouncedSave);
  outcomesField.addEventListener("input", debouncedSave);
  structureField.addEventListener("input", debouncedSave);
  timingField.addEventListener("input", debouncedSave);
}

/**
 * Refresh meeting info (attendees and duration)
 */
async function refreshMeetingInfo(): Promise<void> {
  try {
    // Get attendee count
    const count = await getAttendeeCount();
    const attendeeStatus = getAttendeeStatusMessage(count);
    attendeeCount.textContent = attendeeStatus.message;

    // Apply color coding based on level
    attendeeBadge.classList.remove("success", "warning", "error");
    attendeeBadge.classList.add(attendeeStatus.level);

    // Get duration
    const duration = await getDurationMinutes();
    const durationStatus = getDurationStatusMessage(duration);
    durationText.textContent = durationStatus.message;

    // Apply color coding to duration text
    durationText.classList.remove("success", "warning", "error");
    durationText.classList.add(durationStatus.level);

    // Show/hide duration buttons based on status
    if (durationStatus.showButtons) {
      durationButtons.classList.remove("hidden");
    } else {
      durationButtons.classList.add("hidden");
    }

    // Update timing field with meeting times
    await updateTimingField();
  } catch (error) {
    console.error("Error refreshing meeting info:", error);
    attendeeCount.textContent = "Unable to load";
    durationText.textContent = "Unable to load";
  }
}

/**
 * Update timing field with meeting start/end times
 */
async function updateTimingField(): Promise<void> {
  try {
    const times = await getMeetingTimes();
    const duration = await getDurationMinutes();
    const timingText = `${formatTime(times.start)} - ${formatTime(times.end)} (${duration} min)`;

    // Only update if field is empty or has auto-generated content
    if (!timingField.value || timingField.value.includes(" - ")) {
      timingField.value = timingText;
    }
  } catch (error) {
    console.error("Error updating timing field:", error);
  }
}

/**
 * Handle duration change (30 or 45 min buttons)
 */
async function handleDurationChange(minutes: number): Promise<void> {
  try {
    await setMeetingDuration(minutes);
    showStatus(`Duration set to ${minutes} minutes`, "success");
    await refreshMeetingInfo();
  } catch (error) {
    console.error("Error setting duration:", error);
    showStatus("Failed to update duration", "error");
  }
}

/**
 * Load form data from custom properties
 */
async function loadFormData(): Promise<void> {
  try {
    const data = await loadPostData();
    if (data) {
      purposeField.value = data.purpose;
      outcomesField.value = data.outcomes;
      structureField.value = data.structure;
      if (data.timing) {
        timingField.value = data.timing;
      }
    }
  } catch (error) {
    console.error("Error loading form data:", error);
  }
}

/**
 * Get current form data
 */
function getFormData(): PostData {
  const data: PostData = {
    purpose: purposeField.value,
    outcomes: outcomesField.value,
    structure: structureField.value,
    timing: timingField.value,
    isComplete: false,
    lastUpdated: new Date().toISOString(),
  };

  // Check if all fields are filled
  data.isComplete = validatePostData(data);

  return data;
}

/**
 * Handle Save button click - saves data and inserts POST into body
 */
async function handleSave(silent: boolean = false): Promise<void> {
  try {
    const data = getFormData();
    await savePostData(data);

    // Update field validation states
    updateFieldValidation();

    // If all fields are filled, also insert POST into body
    if (validatePostData(data)) {
      await insertPostIntoBody(data, silent);
    } else if (!silent) {
      showStatus("Saved. Complete all fields to update meeting body.", "info");
    }
  } catch (error) {
    console.error("Error saving:", error);
    if (!silent) {
      showStatus("Failed to save", "error");
    }
  }
}

/**
 * Update field validation visual states
 */
function updateFieldValidation(): void {
  const data = getFormData();
  const validation = validateFields(data);

  setFieldValidation(purposeField, validation.purpose);
  setFieldValidation(outcomesField, validation.outcomes);
  setFieldValidation(structureField, validation.structure);
  setFieldValidation(timingField, validation.timing);
}

/**
 * Set validation class on a field
 */
function setFieldValidation(field: HTMLElement, isValid: boolean): void {
  const value = (field as HTMLInputElement).value?.trim();
  if (!value) {
    field.classList.remove("valid", "invalid");
  } else if (isValid) {
    field.classList.add("valid");
    field.classList.remove("invalid");
  } else {
    field.classList.add("invalid");
    field.classList.remove("valid");
  }
}

/**
 * Insert POST content into meeting body
 */
async function insertPostIntoBody(data: PostData, silent: boolean): Promise<void> {
  return new Promise((resolve) => {
    // Format POST content as HTML
    const postHtml = formatPostHtml(data);

    // Get current body and replace/prepend POST
    Office.context.mailbox.item?.body.getAsync(
      Office.CoercionType.Html,
      (result) => {
        if (result.status === Office.AsyncResultStatus.Failed) {
          if (!silent) {
            showStatus("Failed to read meeting body", "error");
          }
          resolve();
          return;
        }

        const currentBody = result.value || "";

        // Check if POST is already in body - replace it
        if (currentBody.includes("Meeting Overview") || currentBody.includes("MEETING POST")) {
          // Replace existing POST section by setting just the POST HTML
          setMeetingBody(postHtml, silent, resolve);
        } else {
          // Set body to just the POST HTML (overwrites any existing content)
          setMeetingBody(postHtml, silent, resolve);
        }
      }
    );
  });
}

/**
 * Set the meeting body content
 */
function setMeetingBody(html: string, silent: boolean = false, callback?: () => void): void {
  Office.context.mailbox.item?.body.setAsync(
    html,
    { coercionType: Office.CoercionType.Html },
    (result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        if (!silent) {
          showStatus("Saved and updated meeting body", "success");
        }
      } else {
        if (!silent) {
          showStatus("Failed to update meeting body", "error");
        }
      }
      if (callback) callback();
    }
  );
}

/**
 * Format POST data as HTML for meeting body
 */
function formatPostHtml(data: PostData): string {
  // Format outcomes as bullet list
  const outcomeLines = data.outcomes
    .split("\n")
    .filter((line) => line.trim())
    .map((line) => `<li>${escapeHtml(line.replace(/^[-*•]\s*/, ""))}</li>`)
    .join("");

  // Format structure as numbered list
  const structureLines = data.structure
    .split("\n")
    .filter((line) => line.trim())
    .map((line) => `<li>${escapeHtml(line.replace(/^\d+[.)]\s*/, ""))}</li>`)
    .join("");

  return `
<div style="font-family: Segoe UI, sans-serif; padding: 20px; background: #f5f5f5; border-radius: 8px; margin-bottom: 16px;">
  <h2 style="color: #0078d4; margin-top: 0; margin-bottom: 8px;">📌 Meeting Overview</h2>
  <p style="color: #605e5c; margin-top: 0; margin-bottom: 20px; font-style: italic;">This meeting uses the POST framework to keep discussions focused and productive.</p>

  <h3 style="color: #323130; margin-bottom: 4px;">🎯 Purpose</h3>
  <p style="color: #605e5c; margin-top: 0; margin-bottom: 4px; font-size: 12px;">Why we're meeting:</p>
  <p style="margin-top: 0; margin-bottom: 16px;">${escapeHtml(data.purpose)}</p>

  <h3 style="color: #323130; margin-bottom: 4px;">✅ Outcomes</h3>
  <p style="color: #605e5c; margin-top: 0; margin-bottom: 4px; font-size: 12px;">What we aim to achieve:</p>
  <ul style="margin-top: 0; margin-bottom: 16px; padding-left: 20px;">
    ${outcomeLines || "<li>No outcomes specified</li>"}
  </ul>

  <h3 style="color: #323130; margin-bottom: 4px;">🗂 Structure</h3>
  <p style="color: #605e5c; margin-top: 0; margin-bottom: 4px; font-size: 12px;">How the meeting will run:</p>
  <ol style="margin-top: 0; margin-bottom: 16px; padding-left: 20px;">
    ${structureLines || "<li>No structure specified</li>"}
  </ol>

  <h3 style="color: #323130; margin-bottom: 4px;">⏰ Timing</h3>
  <p style="margin-top: 0; margin-bottom: 0;">${escapeHtml(data.timing)}</p>
</div>`.trim();
}

/**
 * Escape HTML special characters
 */
function escapeHtml(text: string): string {
  const div = document.createElement("div");
  div.textContent = text;
  return div.innerHTML;
}

/**
 * Show a status message
 */
function showStatus(
  message: string,
  type: "success" | "error" | "info" = "info"
): void {
  statusMessage.textContent = message;
  statusMessage.className = `status ${type}`;
  statusMessage.classList.remove("hidden");

  // Auto-hide after 3 seconds
  setTimeout(() => {
    statusMessage.classList.add("hidden");
  }, 3000);
}
